struct vector3d
{
  float x;
  float y;
  float z;
  float w;
};

struct quaternion
{
  float a;
  float b;
  float c;
  float d;
};

class po
{
public:
  vector3d get_position() const;
  quaternion get_quaternion() const;
};

class rigid_body
{
public:
  vector3d linMom;
};

class board_controller
{
public:
  vector3d current;
  rigid_body *rb;
};

class entity
{
public:
  po get_rel_po() const;
};

class kelly_slater_controller
{
public:
  po get_owner_po() const;
  board_controller &get_board_controller();
};

class world_dynamics_system
{
public:
  kelly_slater_controller *get_ks_controller(int player);
  entity *get_board_ptr(int player);
};

extern world_dynamics_system *g_world_ptr;

class KSEntityPO
{
  vector3d KSPos;
  vector3d KSBPos;
  quaternion KSRot;
  quaternion KSBRot;
  vector3d BoardCurrent;
  vector3d BoardMomentum;

public:
  void Save(int player);
};

void KSEntityPO::Save( int player )
{
  po KSPo   = g_world_ptr->get_ks_controller(player)->get_owner_po();
  po KSBPo  = g_world_ptr->get_board_ptr(player)->get_rel_po();

  KSPos     = KSPo.get_position();
  KSBPos    = KSBPo.get_position();
  KSRot     = KSPo.get_quaternion();
  KSBRot    = KSBPo.get_quaternion();
  BoardCurrent    = g_world_ptr->get_ks_controller(player)->get_board_controller().current;
  BoardMomentum   = g_world_ptr->get_ks_controller(player)->get_board_controller().rb->linMom;
}
